<?php namespace App\Http\Controllers; use App\Models\{Message,User}; use Illuminate\Http\Request; class MessageController extends Controller { public function index(){return view('messages.index',['messages'=>Message::with(['sender','recipient'])->where('sender_id',auth()->id())->orWhere('recipient_id',auth()->id())->latest()->get()]);} public function store(Request $r,User $recipient){abort_if($recipient->id===auth()->id(),422);$d=$r->validate(['body'=>'required|string|max:5000']);Message::create(['sender_id'=>auth()->id(),'recipient_id'=>$recipient->id,'body'=>$d['body']]);return back()->with('success','Message sent.');} }
